scripts.count_inversions:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']

    # Count inversions: pairs (i, j) where i < j but values[i] > values[j]
    count = 0
    n = len(values)

    for i in range(n):
        for j in range(i + 1, n):
            if values[i] > values[j]:
                count += 1

    return float(count)

scripts.factorial_mod:
def solve(inputs: dict) -> float:
    n = inputs['N']
    mod = inputs['MOD']

    # Compute n! mod mod
    result = 1
    for i in range(1, n + 1):
        result = (result * i) % mod

    return float(result)

scripts.lcg_generator:
def solve(inputs: dict) -> float:
    x = inputs['SEED']
    a = inputs['A']
    b = inputs['B']
    m = inputs['M']
    k = inputs['K']

    # Run k rounds of the LCG: X = (A * X + B) mod M
    for _ in range(k):
        x = (a * x + b) % m

    return float(x)

scripts.gcd_all:
import math

def solve(inputs: dict) -> float:
    values = inputs['VALUES']

    # Compute GCD of all values
    result = values[0]
    for i in range(1, len(values)):
        result = math.gcd(result, values[i])

    return float(result)

